/**
 * In API_PROXY mode every model call goes to the agent, so titles must not be
 * generated by a model call (#239). The title is the first message, trimmed. If
 * the agent were called, the mock agent's reply would come back as the title.
 */

import { generateUUID } from '@databricks/chatbot-core';
import { expect, test } from '../fixtures';

function userMessage(text: string) {
  return { id: generateUUID(), role: 'user', parts: [{ type: 'text', text }] };
}

async function titleFor(
  request: import('@playwright/test').APIRequestContext,
  text: string,
) {
  const response = await request.post('/api/chat/title', {
    data: { message: userMessage(text) },
  });
  expect(response.status()).toBe(200);
  return (await response.json()).title as string;
}

test.describe('/api/chat/title (API_PROXY mode)', () => {
  test('uses the first message as the title instead of running the agent', async ({
    adaContext,
  }) => {
    expect(await titleFor(adaContext.request, 'Why is the sky blue?')).toBe(
      'Why is the sky blue?',
    );
  });

  test('trims long messages at a word boundary', async ({ adaContext }) => {
    const long =
      'Compare the quarterly revenue trends across every region and explain which products drove the change';
    const title = await titleFor(adaContext.request, long);
    expect(title.length).toBeLessThanOrEqual(80);
    expect(long.startsWith(title)).toBe(true);
    expect(long[title.length]).toBe(' ');
  });

  test('collapses line breaks and surrounding whitespace', async ({
    adaContext,
  }) => {
    expect(
      await titleFor(adaContext.request, '  Summarize this:\n\nthe report  '),
    ).toBe('Summarize this: the report');
  });
});
